async function resizeImagePica(n,t=800,i=800,r="base64"){if(!(n instanceof Blob))throw new Error("L'entrée doit être un objet Blob ou File.");const u=document.createElement("img"),h=URL.createObjectURL(n);u.src=h;await new Promise((n,t)=>{u.onload=n,u.onerror=t});let f=u.width,e=u.height;if(f>t||e>i){const n=Math.min(t/f,i/e);f=Math.round(f*n);e=Math.round(e*n)}const s=document.createElement("canvas");s.width=u.width;s.height=u.height;const l=s.getContext("2d");l.drawImage(u,0,0);const o=document.createElement("canvas");o.width=f;o.height=e;const c=window.pica({features:["js","wasm","ww"]});if(await c.resize(s,o,{unsharpAmount:80,unsharpRadius:.6,unsharpThreshold:2}),URL.revokeObjectURL(h),r==="base64")return o.toDataURL("image/jpeg",.7);if(r==="blob")return await c.toBlob(o,"image/jpeg",.7);throw new Error("Type de retour invalide : utilisez 'base64' ou 'blob'");}